function initAudio(){if(audio)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audio=new Audio();master=audio.createGain();master.gain.value=.2;master.connect(audio.destination);const buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);let smooth=0;for(let i=0;i<data.length;i++){smooth=(smooth+Math.random()*.08-.04)*.98;data[i]=smooth;}const source=audio.createBufferSource();source.buffer=buffer;source.loop=true;const low=audio.createBiquadFilter();low.type='lowpass';low.frequency.value=750;roadNoise=audio.createGain();roadNoise.gain.value=.25;source.connect(low);low.connect(roadNoise);roadNoise.connect(master);source.start();}
function setSound(on){initAudio();soundOn=on;if(audio){audio.resume();master.gain.setTargetAtTime(on?.22:0,audio.currentTime,.12);}$('sound').classList.toggle('sound-on',on);$('sound').setAttribute('aria-label',on?'Mute sound':'Enable sound');}
function tone(freq,duration=.13,type='sine',volume=.15,slide){if(!audio||!soundOn)return;const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+duration);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(volume,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(master);o.start();o.stop(t+duration+.02);}
function announce(title,sub='',time=3){$('announcement').innerHTML=title+(sub?`<small>${sub}</small>`:'');$('announcement').classList.add('visible');announceTimer=time;}
function onEvent(type,data){switch(type){
 case 'cue':$('encounter-cue').innerHTML=`<strong>${data.title}</strong><span>${data.detail}</span>`;$('encounter-cue').classList.add('visible');cueTimer=3.5;break;
 case 'flowReady':tone(660,.2,'sine',.13,1320);break;
 case 'flow':announce('IN THE FLOW','POWERED SHOTS · FAST DASH · SLOWED ENEMY FIRE',1.5);tone(130,.8,'sawtooth',.14,760);break;
 case 'purchase':tone(800,.2,'sine',.13,1600);break;case 'support':tone(110,.16,'sawtooth',.08,500);break;case 'blocked':tone(1100,.12,'sine',.1,650);break;case 'powerup':$('power-toast').textContent=data.name+' · '+data.desc;$('power-toast').classList.add('visible');powerToastTimer=3;tone(900,.25,'sine',.13,1600);break;case 'workshop':clearKeys();$('flow-button').classList.add('hidden');$('loot-panel').classList.add('hidden');$('encounter-cue').classList.remove('visible');$('active-buffs').textContent='';mode='workshop';$('announcement').classList.remove('visible');$('boss-hud').classList.add('hidden');$('power-toast').classList.remove('visible');workshop.open(world);break;case 'jump':tone(data.double?550:370,.18,'sine',.12,900);break;case 'shoot':tone(data.charged?340:860,.1,'sawtooth',data.charged?.12:.06,190);tone(data.charged?95:150,.13,'triangle',.12,65);break;case 'slash':tone(170,.055,'triangle',.05,260);break;case 'swing':tone(data.kind==='break'?155:1150,data.kind==='break'?.24:.13,'triangle',.17,data.kind==='rise'?1600:130);break;case 'impact':tone(data.kind==='break'?62:130,.11,'square',.075,38);tone(1550,.055,'sine',.09,640);break;case 'pogo':tone(420,.17,'sine',.16,1180);break;case 'parry':tone(1800,.12,'sine',.1,900);break;case 'dash':tone(150,.22,'sawtooth',.08,900);break;case 'collect':tone(1050,.18,'sine',.14,1500);break;case 'kill':tone(110,.22,'sawtooth',.18,35);break;case 'hurt':tone(85,.3,'square',.1,30);break;case 'bossShot':tone(90,.35,'sawtooth',.12,220);break;case 'overpass':announce(world.stage===2?'HARBOR FLYOVER':'THE OVERPASS','FIND YOUR RHYTHM. TAKE THE HIGH ROAD.');break;case 'braking':announce('RED LIGHT AHEAD','THE CAR IS SLOWING DOWN.',3.5);break;case 'boss':$('boss-hud').classList.remove('hidden');$('boss-name').textContent=world.stageInfo.boss.toUpperCase();announce(world.stageInfo.boss.toUpperCase(),'JUMP THE WAVES. FIRE WHEN THE CORE OPENS.',3.8);break;case 'bossDefeated':$('boss-hud').classList.add('hidden');announce('STAGE CLEAR',world.stage===1?'NEXT STOP: THE WORKSHOP.':'BOTH STAGES COMPLETE.',2.7);tone(660,.6,'sine',.2,1320);break;case 'death':showModal('THE DAYDREAM SLIPPED','Your build is ready. Try this stage again.','RETRY STAGE','KEEP YOUR EYES ON THE WINDOW');break;case 'victory':showModal('SEE YOU NEXT RIDE',`Chapter complete. ${data.score.toLocaleString()} points. You kept the daydream alive.`,'RIDE AGAIN','THE LONG WAY HOME · COMPLETE');break;}}
function begin(){if(!loaded)return;if(mode==='menu'){setSound(true);mode='intro';introTimer=0;$('intro').classList.remove('hidden');stage.classList.add('intro-playing');$('skip').focus();}else if(mode==='intro')play();}
function play(){world.reset(false,{chassis:selectedChassis});enterStage();}
function enterStage(){clearKeys();$('encounter-cue').classList.remove('visible');animation.reset();mode='play';world.paused=false;workshop.close();$('intro').classList.add('hidden');stage.classList.remove('intro-playing');stage.classList.add('playing');$('hud').classList.remove('hidden');$('flow-button').classList.remove('hidden');$('loot-panel').classList.remove('hidden');$('boss-hud').classList.add('hidden');$('modal').classList.add('hidden');$('active-buffs').textContent='';$('power-toast').classList.remove('visible');canvas.focus({preventScroll:true});announce(world.stage===1?'FIND YOUR FLOW':'HARBOR AFTERGLOW',world.stage===1?'↑ JUMP · Z BUSTER · X BLADE · SHIFT DASH':'YOUR NEW BUILD IS ONLINE. KEEP PACE.',2);hudTimer=0;}
function retryStage(){world.retryStage();enterStage();}
function showModal(title,description,action,eyebrow){mode=world.over?'over':'paused';world.paused=true;$('modal-title').textContent=title;$('modal-description').textContent=description;$('resume').innerHTML=`${action} <span>→</span>`;$('modal-eyebrow').textContent=eyebrow;$('modal').classList.remove('hidden');$('resume').focus();}
function pause(){if(mode==='play'){clearKeys();showModal('DAYDREAM PAUSED','The road will be here.','BACK TO THE WINDOW','TAKE A BREATH');}else if(mode==='paused')resume();}
function resume(){if(world.over||mode==='over'){retryStage();return;}mode='play';world.paused=false;$('modal').classList.add('hidden');canvas.focus({preventScroll:true});}
function clearKeys(){for(const k in keys)keys[k]=false;}
$('start').addEventListener('click',begin);$('skip').addEventListener('click',play);$('pause').addEventListener('click',pause);$('resume').addEventListener('click',resume);$('restart').addEventListener('click',retryStage);$('sound').addEventListener('click',()=>setSound(!soundOn));
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else announce('TURN YOUR PHONE SIDEWAYS','LANDSCAPE GIVES YOU THE WHOLE WINDOW.');}catch{announce('FULLSCREEN UNAVAILABLE','YOU CAN KEEP PLAYING IN THIS WINDOW.');}});
$('flow-button').addEventListener('click',()=>{if(mode==='play')world.activateFlow();canvas.focus({preventScroll:true});});
const mappings={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',KeyZ:'shoot',KeyX:'slash',ShiftLeft:'dash',ShiftRight:'dash'};
window.addEventListener('keydown',e=>{if(mode==='workshop')return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyZ','KeyX','KeyC','ShiftLeft','ShiftRight','Escape'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(!e.repeat)pause();return;}if((e.code==='Space'||e.code==='Enter')&&(mode==='menu'||mode==='intro')){if(!e.repeat)begin();return;}if(mode!=='play')return;if(e.code==='KeyC'&&!e.repeat)world.activateFlow();if(e.code==='ArrowUp'&&!e.repeat)world.jump();if(mappings[e.code])keys[mappings[e.code]]=true;if((e.code==='ShiftLeft'||e.code==='ShiftRight')&&!e.repeat)world.requestDash(keys.left&&!keys.right?-1:1);if(e.code==='KeyX'&&!e.repeat)world.slash(keys.down?'down':keys.up?'up':'forward');if(e.code==='KeyZ'&&!e.repeat)world.shoot();});
window.addEventListener('keyup',e=>{if(mappings[e.code])keys[mappings[e.code]]=false;if(e.code==='ArrowUp')world.releaseJump();});window.addEventListener('blur',()=>{clearKeys();if(mode==='play')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='play')pause();});
for(const b of document.querySelectorAll('[data-action]')){const action=b.dataset.action;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(mode!=='play')return;if(action==='flow')world.activateFlow();else if(action==='jump')world.jump();else if(action==='dash')world.requestDash(keys.left&&!keys.right?-1:1);else if(action==='pogo')world.slash('down');else{keys[action]=true;if(action==='slash')world.slash(keys.up?'up':'forward');if(action==='shoot')world.shoot();}});for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,()=>{if(action==='jump')world.releaseJump();if(action!=='jump'&&action!=='pogo')keys[action]=false;});}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h);}
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}
function sprite(index,x,y,width,height,alpha=1,mirror=false){if(!assets.sprites)return;const s=spriteRects[index];ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);if(mirror)ctx.scale(-1,1);ctx.drawImage(assets.sprites,s.x+2,s.y+2,s.w-4,s.h-4,-width/2,-height,width,height);ctx.restore();}
